sys_script_include.script:
var CreateSaaSIntegrationTasks = Class.create();
CreateSaaSIntegrationTasks.prototype = {
    initialize: function() {},

    createTasks: function() {
        var createdTasks = [];
        var processedProperties = []; // Track processed properties

        var propertyName = 'saas.integration.kpi';
        var kpiData = gs.getProperty(propertyName);

        if (!kpiData) {
            gs.error('❌ Sys Property "' + propertyName + '" is empty or not set.');
            return { error: 'No SaaS integration KPI data available' };
        }

        processedProperties.push(propertyName);
        gs.info('🔍 Processing Sys Property: ' + propertyName);

        try {
            var integrations = JSON.parse(kpiData);

            for (var key in integrations) {
                if (integrations.hasOwnProperty(key)) {
                    var integration = integrations[key];

                    if (!integration.description || !integration.recommendation) {
                        gs.error('⚠️ Missing required fields for integration: ' + key);
                        continue;
                    }

                    // Check if task already exists
                    var existingTask = new GlideRecord('samp_sp_vb_task');
                    existingTask.addQuery('name', key);
                    existingTask.addQuery('description', integration.description);
                    existingTask.addEncodedQuery('stateNOT IN2,-5,3,7');
                    existingTask.query();
                    if (existingTask.next()) {
                        gs.info('✅ Task already exists for integration: ' + key);
                        continue;
                    }

                    // Create new task
                    var taskGr = new GlideRecord('samp_sp_vb_task');
                    taskGr.initialize();
                    taskGr.setValue('name', key);
                    taskGr.setValue('short_description', integration.description);
                    taskGr.setValue('description', integration.description);
                    taskGr.setValue('instructions', integration.recommendation);

                    var taskId = taskGr.insert();
                    if (taskId) {
                        gs.info('🆕 Created task for integration: ' + key + ' (Task ID: ' + taskId + ')');
                        createdTasks.push(key);
                        gs.eventQueue('saas.integration.value.builder.task', taskGr, taskGr.sys_id);
                    }
                }
            }
        } catch (e) {
            gs.error('🚨 Error processing sys_property "' + propertyName + '": ' + e.message);
        }

        return {
            createdTasks: createdTasks,
            processedProperties: processedProperties
        };
    },

    type: 'CreateSaaSIntegrationTasks'
};
